/* Fleet build watch: "New version available · Reload".
 *
 * VENDORED VERBATIM from project-scaffolding. Do NOT edit this file per-app:
 * the endpoint and the reader are options. Normalized from app-launcher's
 * build-watch.js.
 *
 * Notices that the server moved to a newer build while this page stayed open.
 * Every /static URL carries the fleet content hash as ?v=, so this module's
 * own URL (or, failing that, any stamped asset the page linked) says which
 * build the page booted on; the version endpoint's `asset_hash` says which
 * build is live now. A phone PWA that sat in memory across a restart keeps the
 * old shell and modules until it is reloaded, so a differing pair offers a
 * Reload. Nothing reloads by itself: an unsent draft must survive.
 *
 * Unknown is never stale: no boot stamp (a dev tree), an empty or missing
 * `asset_hash`, a failed read or a 401 all leave the prompt down.
 *
 * Pairs with build-watch.css, which lays the prompt out on the vendored
 * toast's glass (toast.css).
 */

'use strict';

// A visibility check is skipped when the last good read is younger than this,
// so flicking between apps does not hammer the version endpoint.
export const CHECK_THROTTLE_MS = 60 * 1000;
// A page left visible and untouched still checks, this often.
export const CHECK_INTERVAL_MS = 5 * 60 * 1000;

// Lucide `x`, inline so the dismiss works without the app's icon sprite.
const DISMISS_GLYPH =
  '<svg class="icon" viewBox="0 0 24 24" width="16" height="16" fill="none" ' +
  'stroke="currentColor" stroke-width="2" stroke-linecap="round" ' +
  'stroke-linejoin="round" aria-hidden="true"><path d="M18 6 6 18"/>' +
  '<path d="m6 6 12 12"/></svg>';

/**
 * 'stale' only when both hashes are known and differ; else 'current' or
 * 'unknown'. Some apps' versioning answers the literal 'missing' for a hash it
 * could not compute, which is unknown too.
 */
export function verdict(bootHash, liveHash) {
  const known = (h) => typeof h === 'string' && h !== '' && h !== 'missing';
  if (!known(bootHash) || !known(liveHash)) return 'unknown';
  return bootHash === liveHash ? 'current' : 'stale';
}

/**
 * Whether a trigger at nowMs should read the server: never read ok, or the
 * last ok read is at least the throttle old. Only an ok read counts, so a read
 * that landed mid-restart is retried on the next trigger.
 */
export function shouldCheck(nowMs, lastOkMs, throttleMs) {
  if (typeof lastOkMs !== 'number') return true;
  return nowMs - lastOkMs >= throttleMs;
}

/** The ?v= stamp on a URL, or null when it has none. */
export function stampOf(url) {
  if (typeof url !== 'string' || url === '') return null;
  try {
    return new URL(url, 'http://stamp.invalid/').searchParams.get('v') || null;
  } catch (_) {
    return null;
  }
}

// The build the page booted on. The shell is served no-cache, so its stamps
// are the boot build's. The entry module script comes first: an app that
// stamps each file with its own hash reports that script's stamp as
// asset_hash, and with one fleet hash every stamp agrees anyway. Then this
// module's own stamp (an app that rewrites JS imports), then any stamped
// script or stylesheet.
function bootStamp() {
  const entry = document.querySelector('script[type="module"][src*="?v="]');
  const fromEntry = entry ? stampOf(entry.src) : null;
  if (fromEntry) return fromEntry;
  const own = stampOf(import.meta.url);
  if (own) return own;
  const assets = document.querySelectorAll('script[src*="?v="], link[rel="stylesheet"][href*="?v="]');
  for (const el of assets) {
    const stamp = stampOf(el.src || el.href);
    if (stamp) return stamp;
  }
  return null;
}

async function fetchJsonDefault(url) {
  const res = await fetch(url, { cache: 'no-store', credentials: 'same-origin' });
  if (!res.ok) throw new Error('version read failed');
  return res.json();
}

function buildPrompt(onReload, onDismiss) {
  const root = document.createElement('div');
  root.id = 'buildPrompt';
  root.className = 'toast build-prompt';
  root.setAttribute('role', 'status');
  root.setAttribute('aria-live', 'polite');

  const text = document.createElement('span');
  text.className = 'build-prompt-text';
  text.textContent = 'New version available';

  const reload = document.createElement('button');
  reload.type = 'button';
  reload.className = 'button-primary build-prompt-reload';
  reload.dataset.track = 'build.reload';
  reload.textContent = 'Reload';
  reload.addEventListener('click', onReload);

  const close = document.createElement('button');
  close.type = 'button';
  close.className = 'icon-button build-prompt-dismiss';
  close.dataset.track = 'build.dismiss';
  close.title = 'Dismiss';
  close.setAttribute('aria-label', 'Dismiss');
  close.innerHTML = DISMISS_GLYPH;
  close.addEventListener('click', onDismiss);

  root.append(text, reload, close);
  return root;
}

/**
 * Start watching. Returns false (and does nothing) when the page has no boot
 * stamp to compare against.
 *
 * @param {{endpoint?: string, fetchJson?: (url: string) => Promise<any>}} [opts]
 *   `endpoint` is the build-identity route (default `/api/version`, which must
 *   return the fleet hash as `asset_hash`); `fetchJson` replaces the default
 *   same-origin `fetch` for an app whose API reads add their own auth. It must
 *   reject on a non-2xx answer.
 * @returns {boolean} whether the watch started.
 */
export function initBuildWatch(opts) {
  const endpoint = (opts && opts.endpoint) || '/api/version';
  const readJson = (opts && opts.fetchJson) || fetchJsonDefault;
  const boot = bootStamp();
  if (!boot) return false;
  let lastOk = null;
  let dismissedFor = null;
  let prompt = null;
  let inFlight = false;

  function hidePrompt() {
    if (prompt) prompt.hidden = true;
  }

  function showPrompt(live) {
    if (!prompt) {
      prompt = buildPrompt(
        function () { location.reload(); },
        function () { dismissedFor = prompt.dataset.live; hidePrompt(); },
      );
      document.body.appendChild(prompt);
    }
    prompt.dataset.live = live;
    prompt.hidden = false;
  }

  async function check() {
    if (inFlight) return;
    inFlight = true;
    try {
      const body = await readJson(endpoint);
      lastOk = Date.now();
      const live = body && body.asset_hash;
      if (verdict(boot, live) !== 'stale') {
        hidePrompt();
        return;
      }
      // A dismissed prompt stays down until the server moves to another build.
      if (live === dismissedFor) return;
      showPrompt(live);
    } catch (_) {
      // Unknown, not stale: say nothing and try again on the next trigger.
    } finally {
      inFlight = false;
    }
  }

  document.addEventListener('visibilitychange', function () {
    if (document.hidden) return;
    if (shouldCheck(Date.now(), lastOk, CHECK_THROTTLE_MS)) check();
  });
  setInterval(function () {
    if (!document.hidden) check();
  }, CHECK_INTERVAL_MS);
  return true;
}
